import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 표시 건수 기본은 최근 10건 (AC-FN-SFR-027-04-8)
const DEFAULT_SIZE = 10;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr02704Controller {
  @Get('/access-logs/recent-menus')
  async listRecentMenus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    const size = sizeRaw === undefined || sizeRaw === '' ? DEFAULT_SIZE : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '건수는 1 이상 200 이하의 정수여야 합니다.');
    }
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT a.menu_id AS "menuId",
                a.accessed_at AS "accessedAt",
                m.name AS "menuName"
           FROM access_log a
           JOIN menu m ON m.menu_id = a.menu_id
          WHERE a.employee_id = CAST(:userId AS bigint)
            AND a.event_type = '메뉴사용'
          ORDER BY a.accessed_at DESC, a.access_log_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { userId: user.id, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM access_log a
           JOIN menu m ON m.menu_id = a.menu_id
          WHERE a.employee_id = CAST(:userId AS bigint)
            AND a.event_type = '메뉴사용'`,
        { userId: user.id },
      );
      const total = Number(counts[0]?.['total'] ?? 0);
      return { items, page, size, total };
    });
  }
}

