import { useState } from 'react';
import {
  call,
  useData,
  Num,
  DateText,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 10;

export default function FnSfr02704Page({ role }: PageProps) {
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/access-logs/recent-menus', role, undefined, { page, size: SIZE }),
    [page, role],
  );

  const rows = data?.items ?? [];
  const total = data?.total ?? 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>최근 사용 건수</h2>
        <Num value={total} />
      </section>
      <section className="box span-8">
        <h2>최근 사용 메뉴</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'menuName', label: '메뉴명' },
            {
              key: 'accessedAt',
              label: '접속·사용 일시',
              render: (row) => <DateText value={row.accessedAt} time />,
            },
          ]}
          rows={rows}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '불러오는 중입니다.' : '최근 사용한 메뉴 이력이 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      {selected ? (
        <Drawer title="메뉴 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['메뉴명', String(selected.menuName ?? '')],
              ['접속·사용 일시', <DateText value={selected.accessedAt} time />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
